27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "membership_number")
67	    private String membershipNumber;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    public String getHouseholdId() {
127	        return this.householdId;
128	    }
129	
130	    public void setHouseholdId(String householdId) {
131	        this.householdId = householdId;
132	    }
133	
134	    public Integer getNamesakeCount() {
135	        return this.namesakeCount;
136	    }
137	
138	    public void setNamesakeCount(Integer namesakeCount) {
139	        this.namesakeCount = namesakeCount;
140	    }
141	
142	    public String getMembershipNumber() {
143	        return this.membershipNumber;
144	    }
145	
146	    public void setMembershipNumber(String membershipNumber) {
147	        this.membershipNumber = membershipNumber;
148	    }
149	
150	    public Boolean getBulkSignupWarning() {
151	        return this.bulkSignupWarning;
152	    }
153	
154	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
155	        this.bulkSignupWarning = bulkSignupWarning;
156	    }
157	
158	    public Integer getHouseholdSize() {
159	        return this.householdSize;
160	    }
161	
162	    public void setHouseholdSize(Integer householdSize) {
163	        this.householdSize = householdSize;
164	    }
165	
166	    /**
167	     * The owner's membership level, a number from 1 to 3 derived at read time from stored fields.
168	     * Starts at 1; add 1 when an email is present; add 1 when {@link #getNamesakeCount() namesakeCount}
169	     * is 0; capped at 3 (level 4 is reserved for tenure).
170	     */
171	    @Transient
172	    public Integer getMembershipLevel() {
173	        int level = 1;
174	        boolean hasEmail = this.email != null && !this.email.isBlank();
175	        if (hasEmail) {
176	            level++;
177	        }
178	        if (this.namesakeCount != null && this.namesakeCount == 0) {
179	            level++;
180	        }
181	        return Math.min(level, 3);
182	    }
183	
184	    /**
185	     * The owner's region, derived at read time from the {@link #getCity() city} using a fixed
186	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}).
187	     * Any city not in the table yields {@code 'UNKNOWN'}.
188	     */
189	    @Transient
190	    public String getLocality() {
191	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
192	    }
193	
194	    /**
195	     * The owner's preferred contact channel, derived at read time: {@code 'EMAIL'} when an
196	     * {@link #getEmail() email} is present, otherwise {@code 'PHONE'}.
197	     */
198	    @Transient
199	    public String getContactPreference() {
200	        boolean hasEmail = this.email != null && !this.email.isBlank();
201	        return hasEmail ? "EMAIL" : "PHONE";
202	    }
203	
204	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
205	    private static final Map<String, String> CITY_REGION =
206	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
207	
208	    protected Set<Pet> getPetsInternal() {
209	        if (this.pets == null) {
210	            this.pets = new HashSet<>();
211	        }
212	        return this.pets;
213	    }
214	
215	    protected void setPetsInternal(Set<Pet> pets) {
216	        this.pets = pets;
217	    }
218	
219	    public List<Pet> getPets() {
220	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
221	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
222	        return Collections.unmodifiableList(sortedPets);
223	    }
224	
225	    public void setPets(List<Pet> pets) {
226	        this.pets = new HashSet<>(pets);
227	    }
228	
229	    public void addPet(Pet pet) {
230	        getPetsInternal().add(pet);
231	        pet.setOwner(this);
232	    }
233	
234	    /**
235	     * Return the Pet with the given name, or null if none found for this Owner.
236	     *
237	     * @param name to test
238	     * @return true if pet name is already in use
239	     */
240	    public Pet getPet(String name) {
241	        return getPet(name, false);
242	    }
243	
244	    /**
245	     * Return the Pet with the given name, or null if none found for this Owner.
246	     *
247	     * @param name to test
248	     * @return true if pet name is already in use
249	     */
250	    public Pet getPet(String name, boolean ignoreNew) {
251	        name = name.toLowerCase();
252	        for (Pet pet : getPetsInternal()) {
253	            if (!ignoreNew || !pet.isNew()) {
254	                String compName = pet.getName();
255	                compName = compName.toLowerCase();
256	                if (compName.equals(name)) {
257	                    return pet;
258	                }
259	            }
260	        }
261	        return null;
262	    }
263	
264	    public Pet getPet(Integer petId) {
265	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
266	    }
267	
268	    @Override
269	    public String toString() {
270	        return new ToStringCreator(this)
271	
272	            .append("id", this.getId())
273	            .append("new", this.isNew())
274	            .append("lastName", this.getLastName())
275	            .append("firstName", this.getFirstName())
276	            .append("address", this.address)
277	            .append("city", this.city)
278	            .append("telephone", this.telephone)
279	            .toString();
280	    }
281	}
