9	/**
10	 * Runs after {@link NormalizeOwnerTelephone} and before {@link BuildOwner} in the create-owner
11	 * pipeline. Rejects a request whose normalized telephone is already used by any existing owner
12	 * with a 409, so the same phone number is never registered twice.
13	 */
14	public class EnsureUniqueTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateTelephoneException {
18	        String telephone = request.getTelephone();
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (telephone.equals(existing.getTelephone())) {
21	                throw new DuplicateTelephoneException(telephone);
22	            }
23	        }
24	    }
25	}
