6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;
8	
9	/**
10	 * Runs after {@link NormalizeOwnerEmail} and before {@link BuildOwner} in the create-owner
11	 * pipeline. Email is optional: a request that omits it (null or blank) passes through untouched.
12	 * When present, its lower-cased value is compared against the lower-cased email of every existing
13	 * owner; a match is rejected with a 409 so the same email is never registered twice.
14	 */
15	public class EnsureUniqueEmail {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateEmailException {
19	        String email = request.getEmail();
20	        if (email == null || email.isBlank()) {
21	            return;
22	        }
23	        String normalized = email.toLowerCase();
24	        for (Owner existing : ownerRepository.findAll()) {
25	            String existingEmail = existing.getEmail();
26	            if (existingEmail != null && normalized.equals(existingEmail.toLowerCase())) {
27	                throw new DuplicateEmailException(email);
28	            }
29	        }
30	    }
31	}
