1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.UUID;
7	
8	import net.officefloor.plugin.variable.Out;
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
14	
15	/**
16	 * Runs in the create-owner pipeline before {@link BuildOwner}. Compares the request's lastName
17	 * (case-insensitively with collapsed whitespace) and its {@link OwnerAddresses#normalize normalized}
18	 * address against every existing owner. When they
19	 * match an existing owner and the request did NOT set {@code sharesHousehold} true, the request is
20	 * rejected with a 409 so the same household is not registered twice.
21	 *
22	 * <p>When {@code sharesHousehold} is true, a match is instead permitted: this step derives a stable
23	 * shared {@code householdId} from the canonical lastName and address, stamps it onto the matching
24	 * existing owner(s) that lack one, and publishes it as an {@link Out} so {@link AssignHousehold}
25	 * can stamp the same value onto the owner being created. Owners in the same household therefore
26	 * carry an identical, stable identifier. A request with no matching owner publishes {@code null}
27	 * (there is no household to share).
28	 */
29	public class EnsureUniqueHousehold {
30	
31	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository,
32	            Out<HouseholdId> householdIdOut) throws DuplicateHouseholdException {
33	        String lastName = canonical(request.getLastName());
34	        String address = OwnerAddresses.normalize(request.getAddress());
35	
36	        List<Owner> matches = new ArrayList<>();
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (lastName.equals(canonical(existing.getLastName()))
39	                    && address.equals(OwnerAddresses.normalize(existing.getAddress()))) {
40	                matches.add(existing);
41	            }
42	        }
43	
44	        if (matches.isEmpty()) {
45	            householdIdOut.set(null); // unique household — nothing to share
46	            return;
47	        }
48	
49	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
50	            throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
51	        }
52	
53	        // Caller opted into sharing: give this owner and every match the same stable identifier.
54	        String householdId = deriveHouseholdId(lastName, address);
55	        for (Owner match : matches) {
56	            if (match.getHouseholdId() == null) {
57	                match.setHouseholdId(householdId);
58	                ownerRepository.save(match);
59	            }
60	        }
61	        householdIdOut.set(new HouseholdId(householdId));
62	    }
63	
64	    /** Deterministic, stable identifier for a household — same lastName + address always yields it. */
65	    private static String deriveHouseholdId(String canonicalLastName, String canonicalAddress) {
66	        String seed = "household:" + canonicalLastName + "|" + canonicalAddress;
67	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
68	    }
69	
70	    /** Trim, collapse internal whitespace runs to a single space and lower-case for comparison. */
71	    private static String canonical(String value) {
72	        if (value == null) {
73	            return "";
74	        }
75	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
76	    }
77	}
