6	/**
7	 * Runs in the create-owner pipeline after {@link BuildOwner}. Stamps the shared household identifier
8	 * derived by {@link EnsureUniqueHousehold} onto the owner being created so it is stored and returned.
9	 * When the request did not join an existing household the identifier is {@code null} and the owner
10	 * keeps none.
11	 */
12	public class AssignHousehold {
13	
14	    public void service(@Val Owner owner, @Val HouseholdId householdId) {
15	        if (householdId != null && householdId.value() != null) {
16	            owner.setHouseholdId(householdId.value());
17	        }
18	    }
19	}
