1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Shared address normalization for the create-owner pipeline. A single canonical form is used both
7	 * for what is stored and returned and for every address comparison (household duplicate detection
8	 * and the shared household id), so that inputs differing only in surrounding/repeated whitespace,
9	 * letter case or a common street-type abbreviation are treated as the same address.
10	 *
11	 * <p>Rules: trim, collapse internal whitespace runs to a single space, upper-case, then expand the
12	 * common street-type abbreviations {@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE} as
13	 * whole space-separated words. The transform is idempotent. A {@code null} or all-whitespace input
14	 * normalizes to the empty string, so the create-time required-field check rejects it.
15	 */
16	public final class OwnerAddresses {
17	
18	    private static final Map<String, String> ABBREVIATIONS =
19	            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
20	
21	    private OwnerAddresses() {
22	    }
23	
24	    public static String normalize(String raw) {
25	        if (raw == null) {
26	            return "";
27	        }
28	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase();
29	        if (collapsed.isEmpty()) {
30	            return "";
31	        }
32	        String[] tokens = collapsed.split(" ");
33	        StringBuilder normalized = new StringBuilder(collapsed.length());
34	        for (int i = 0; i < tokens.length; i++) {
35	            if (i > 0) {
36	                normalized.append(' ');
37	            }
38	            normalized.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
39	        }
40	        return normalized.toString();
41	    }
